import{_ as a,a0 as s,w as p,s as n,I as r,x as o,a1 as l,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何為你的科技書籍找到出版商 | LCTT x X-CMD","titleTemplate":false,"description":"如何為你的科技書籍找到出版商 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為你的科技書籍找到出版商 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為你的科技書籍找到出版商 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 How to find a publisher for your tech book","title":"如何為你的科技書籍找到出版商","tag":"201712","desc":""},"relativePath":"201712/20171201 How to find a publisher for your tech book.md","filePath":"[post].md"}'),u={name:"201712/20171201 How to find a publisher for your tech book.md"};function f(m,t,b,h,k,T){const e=s("Link");return p(),n("div",null,[t[23]||(t[23]=r("h1",{id:"如何為你的科技書籍找到出版商",tabindex:"-1"},[o("如何為你的科技書籍找到出版商 "),r("a",{class:"header-anchor",href:"#如何為你的科技書籍找到出版商","aria-label":"Permalink to “如何為你的科技書籍找到出版商”"},"​")],-1)),t[24]||(t[24]=r("blockquote",null,[r("p",null,"想去寫一本科技書籍是一個好的想法，但你還需要去了解一下出版業的運作過程。")],-1)),t[25]||(t[25]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDUCATION_colorbooks.png?itok=vNhsYYyC",alt:"How to find a publisher for your tech book",title:"How to find a publisher for your tech book"})],-1)),t[26]||(t[26]=r("p",null,"你有一個寫本科技書籍的想法，那麼祝賀你！就像在阿巴拉契亞山脈徒步旅行，或者是去學做一種蛋奶酥，寫書是人們經常討論的話題之一，但是卻都只停留在思考的初級階段。那是可以理解的，因為失敗的幾率是很高的。要想實現它，你需要在把自己的想法闡述給出版商，去探討是否已經做好充分的準備去寫成一本書。要去實現這一步是相當困難的，但缺乏關於如何做這件事的信息會使事情變得複雜。",-1)),r("p",null,[t[1]||(t[1]=o("如果你想和一家傳統的出版商合作，那麼你需要在他們面前推銷你的書稿以期望能夠得到出版的機會。因為我是 ",-1)),l(e,{href:"https://pragprog.com/"},{default:i(()=>[...t[0]||(t[0]=[o("Pragmatci Bookshelf",-1)])]),_:1}),t[2]||(t[2]=o(" 的總編，所以經常看到很多的選題，也去幫助作者製作出好的作品。這些選題中有些是好的，有些則不然，但我經常會看到許多不符合我們出版社風格的文稿。我會幫助你找到最適合的出版商，來讓你的想法得到認可。",-1))]),t[27]||(t[27]=d('<h3 id="確定你的目標" tabindex="-1">確定你的目標 <a class="header-anchor" href="#確定你的目標" aria-label="Permalink to “確定你的目標”">​</a></h3><p>你的第一步是要找出最適合你的想法的出版商。首先，想想你經常買書的以及你喜歡的出版商，你的書會被像你自己一樣的人喜歡的幾率是很高的，所以從你自己最喜歡的出版商開始，列出一個簡短的列表將會大大縮小你的搜索範圍。如果你自己所買的書籍並不多。那麼可以去書店逛逛，或者在亞馬遜網站上看看。 列一個你自己喜歡的幾家出版商的清單出來。</p><p>下一步，篩選出你期望的出版商，儘管大多數技術類出版商看起來沒什麼差別，但他們通常各有不同的讀者羣體。有些出版商會選擇廣受歡迎的話題，如 C++ 或者 Java，那麼你以 Elixir 為主題的書稿就可能不適合那個出版商；如果你的書稿是關於教授小孩學習編程的，那麼你可能就不想讓學術出版商來出版。</p><p>一旦確定了一些目標，你就可以在他們的商品目錄、網站或者亞馬遜上對其進行進一步的調查，去尋找有哪些書籍和你的思想是相符的。如果他們能有一本和你自己的書稿主題一樣或很相近的書，那麼你將很難説服他們和你簽約。但那並不意味着已經可以把這樣的出版商從你的列表中劃掉，你可以將自己的書稿主題進行適當的修改以將它和已經發行的書區別開來：比如定位於不同的讀者羣體，或者不同層次的技能水平。也許已發行的那本書已經過時了，你就可以專注於該技術領域裏的新方法，確保你的書稿能夠彌補現有書的不足，更加完善，而不是單純的競爭。</p><p>如果你鎖定的出版商沒有出版過類似的書籍，也許這將會是個好跡象，但也許是個壞跡象。有時候一些供應商不會選擇去出版一些專業技術方面的書籍，或者是因為他們認為自己的讀者不會感興趣，也可能是因為他們曾經在這塊領域遇到過麻煩。新的語言或者類庫一直在不停地湧現出來，出版商們不得不去琢磨什麼樣的書籍內容將會吸引他們的讀者羣體。他們的評估標準可能和你的是不一樣的。他們已經有了最終決定，也可能是還在等待合適的選題。判斷究竟是哪一種的唯一方法就是提出文稿並找出答案。</p><h3 id="建立起你自己的網絡" tabindex="-1">建立起你自己的網絡 <a class="header-anchor" href="#建立起你自己的網絡" aria-label="Permalink to “建立起你自己的網絡”">​</a></h3><p>確定一家出版商是第一步；現在你需要與其建立聯繫。不幸的是，出版需要的仍舊是你認識什麼人，而不是你知道什麼。你需要認識的那個人是一個去發現新市場、新作者和新選題的策劃編輯。如果你認識某個和出版商有關係的人，請他給你介紹一位策劃編輯。這些策劃編輯往往負責一個專題板塊，尤其是在較大的出版商，但你並非一定要找到符合你書稿的專題板塊的編輯。各類板塊的編輯通常都會很樂意將你介紹給合適的編輯。</p><p>有時候你也許能夠在一個技術會議上找到一個策劃編輯，特別是在出版商同時也是贊助商，而且還有一個展台時。即使當時並沒有一個策劃編輯在場，展台的其他工作人員也能夠幫你和策劃編輯建立聯繫。 如果會議不符合你的主題思想，那就需要你利用自己的社交網絡來獲得別人的推薦。比如使用 LinkedIn，或者其他非正式的聯繫方式，去和一個編輯建立聯繫。</p><p>對於小型的出版商，你可能會在公司網站上發現策劃編輯的名單，如果你夠幸運的話，還可以找到他們的聯繫信息。如果找不到聯繫方式的話，可以在推特上搜尋出版商的名字，試試能否找到他們的編輯的信息，在社交媒體上去尋找一位陌生的人，然後把自己的書稿推薦給他，這也許會讓你有些緊張，但是你真的不必去擔心這些，建立聯繫也是策劃編輯的工作之一。最壞的結果只不過是他們忽視你而已。</p><p>一旦建立起聯繫，策劃編輯將會協助你進行下一步。他們可能會立刻對你的書稿給予反饋，或者在他們可能想讓你根據他們的指導來修改你的文章，使其變得更加充實。當你經過努力找到了一名策劃編輯後，多聽從他們的建議，因為他們比你更熟悉出版商的運作流程。</p><h3 id="如果其他的方法都失敗了" tabindex="-1">如果其他的方法都失敗了 <a class="header-anchor" href="#如果其他的方法都失敗了" aria-label="Permalink to “如果其他的方法都失敗了”">​</a></h3><p>如果你無法聯繫到一名策劃編輯，出版商通常會有一個<ruby>書稿盲投<rt>proposal alias</rt></ruby>的方式來接受投稿，通常是 <code>proposals@[publisher].com</code> 的格式。 查找他們網站的介紹，找到如何去發送書稿；有的出版商是有特殊的要求的。你需要遵循他們的要求，如果不這樣做的話，你的書稿將會被丟棄，它不會被任何人閲讀。如果你有疑問，或者不確定出版商的意圖，那麼你需要再嘗試着去找一名編輯進一步地溝通，因為書稿並不能回答那些問題。整理他們對你的要求（一篇獨立的主題文章），發給他們，然後你要做的就是期望能夠得到滿意的答覆。</p><h3 id="等待" tabindex="-1">等待 <a class="header-anchor" href="#等待" aria-label="Permalink to “等待”">​</a></h3><p>無論你是如何與一個出版商取得聯繫的，你也得等待着。如果你已經投遞了書稿，也許要過一段時間才有人去處理你的稿件，特別是在一些大公司。即使你已經找了一位策劃編輯去處理你的投稿，你可能也只是他同時在處理的潛在目標之一，所以你可能不會很快得到答覆。幾乎所有的出版商都會在最終確認之前召開一次組委會來決定接受哪個稿件，所以即使你的書稿已經足夠的優秀，並且可以出版了，你也仍然需要等待組委會開會討論。你可能需要等待幾周，甚至是一個月的時間。</p><p>幾周過後，你可以和編輯再聯繫一下，看看他們是否需要更多的信息。在郵件中你要表現出足夠的禮貌；如果他們仍然沒有回覆，也許是因為他們有太多的投稿需要處理，即使你不停地催促也不會讓你的稿件被提前處理。一些出版商有可能永遠不會回覆你，也不會去發一份退稿的通知給你，但那種情況並不常見。在這種情況下你除了耐心地等待也沒有別的辦法，如果幾個月後也沒有人回覆你郵件，你完全可以去接觸另一個出版商或者乾脆考慮自出版。</p><h3 id="祝好運" tabindex="-1">祝好運 <a class="header-anchor" href="#祝好運" aria-label="Permalink to “祝好運”">​</a></h3><p>如果你覺得這個過程看起來讓你感覺有些混亂和不科學，這是很正常的。能夠得到出版要在合適的時間地點，與合適的人溝通，而且還要期待他們此時有好的心情。你無法去控制這些不確定的因素，但是更好地瞭解行業的工作方式，以及出版商的需求，可以幫助你完善它們。</p>',17)),r("p",null,[t[5]||(t[5]=o("尋找一個出版商只是萬里長征的第一步。你需要提煉你的思想，並創建選題，以及其他方面的考慮。在今年的 SeaGLS 上，我對整個過程做了",-1)),l(e,{href:"https://archive.org/details/SeaGL2017WritingTheNextGreatTechBook"},{default:i(()=>[...t[3]||(t[3]=[o("介紹",-1)])]),_:1}),t[6]||(t[6]=o("。查看",-1)),l(e,{href:"https://archive.org/details/SeaGL2017WritingTheNextGreatTechBook"},{default:i(()=>[...t[4]||(t[4]=[o("視頻",-1)])]),_:1}),t[7]||(t[7]=o("可以獲取更詳細的信息。",-1))]),t[28]||(t[28]=r("h3",{id:"關於作者",tabindex:"-1"},[o("關於作者 "),r("a",{class:"header-anchor",href:"#關於作者","aria-label":"Permalink to “關於作者”"},"​")],-1)),r("p",null,[l(e,{href:"https://opensource.com/users/bmacdonald"},{default:i(()=>[...t[8]||(t[8]=[r("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/portrait.jpg?itok=b77dlNC4",alt:""},null,-1)])]),_:1})]),t[29]||(t[29]=r("p",null,"麥克唐納先生現在是 Pragmatic Bookshelf 的總編。過去 20 年在技術出版領域生涯中，他是一名編輯、一名作者，偶爾還去客串演講者或者講師。他現在把大量的時間都用來和新作者探討如何更好地表達出他們的想法。你可以關注他的推特@bmac_editor。",-1)),t[30]||(t[30]=r("p",null,"如果這篇文章點燃你寫書的熱情，但又不知道如何找到合適的途徑聯繫出版商，不如逛逛像異步社區這樣的網站，按照上文的步驟嘗試一下，也許能夠發現新的希望。",-1)),t[31]||(t[31]=r("hr",null,null,-1)),r("p",null,[t[10]||(t[10]=o("via: ",-1)),l(e,{href:"https://opensource.com/article/17/12/how-find-publisher-your-book"},{default:i(()=>[...t[9]||(t[9]=[o("https://opensource.com/article/17/12/how-find-publisher-your-book",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=o("作者：",-1)),l(e,{href:"https://opensource.com/users/bmacdonald"},{default:i(()=>[...t[11]||(t[11]=[o("Brian MacDonald",-1)])]),_:1}),t[15]||(t[15]=o(" 譯者：",-1)),l(e,{href:"https://github.com/FelixYFZ"},{default:i(()=>[...t[12]||(t[12]=[o("FelixYFZ",-1)])]),_:1}),t[16]||(t[16]=o(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1}),t[17]||(t[17]=o(", 陳聰聰",-1))]),r("p",null,[t[20]||(t[20]=o("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[18]||(t[18]=[o("LCTT",-1)])]),_:1}),t[21]||(t[21]=o(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[o("Linux中國",-1)])]),_:1}),t[22]||(t[22]=o(" 榮譽推出",-1))])])}const y=a(u,[["render",f]]);export{C as __pageData,y as default};
